"use client";

import { useState } from "react";
import { importFromSpotlightUrl, uploadSpotlightPdf } from "./actions";

export default function ImportActorPage() {
  const [mode, setMode] = useState<"url" | "pdf">("url");

  return (
    <div className="max-w-3xl">
      <h1 className="text-2xl font-display font-semibold mb-4">Import Actor from Spotlight</h1>
      <p className="text-sm text-neutral-600 mb-6">
        Use a Spotlight URL or upload a Spotlight CV PDF to quickly create an actor profile.
      </p>

      {/* Mode toggle */}
      <div className="inline-flex rounded-full border border-neutral-200 bg-neutral-50 p-1 mb-6">
        <button
          type="button"
          onClick={() => setMode("url")}
          className={`px-4 py-1.5 text-sm rounded-full ${
            mode === "url" ? "bg-white shadow-sm text-neutral-900" : "text-neutral-500"
          }`}
        >
          Import from URL
        </button>
        <button
          type="button"
          onClick={() => setMode("pdf")}
          className={`px-4 py-1.5 text-sm rounded-full ${
            mode === "pdf" ? "bg-white shadow-sm text-neutral-900" : "text-neutral-500"
          }`}
        >
          Upload Spotlight CV (PDF)
        </button>
      </div>

      {mode === "url" && (
        <form action={importFromSpotlightUrl} className="space-y-4 bg-white border border-neutral-200 rounded-xl p-6">
          <div>
            <label className="block text-sm font-medium mb-1">Spotlight profile URL</label>
            <input
              name="spotlight_url"
              required
              placeholder="https://www.spotlight.com/..."
              className="w-full rounded-lg border border-neutral-300 px-3 py-2 text-sm"
            />
          </div>

          <p className="text-xs text-neutral-600">
            We will fetch the public Spotlight page, extract the actor details using AI, and add them to your roster. You
            can edit the profile afterwards.
          </p>

          <button
            type="submit"
            className="px-6 py-2 rounded-full bg-brand-primary text-white text-sm font-medium hover:bg-brand-primary/90 transition"
          >
            Import from URL
          </button>
        </form>
      )}

      {mode === "pdf" && (
        <form action={uploadSpotlightPdf} className="mt-4 space-y-4 bg-white border border-neutral-200 rounded-xl p-6">
          <div>
            <label className="block text-sm font-medium mb-1">Spotlight CV (PDF)</label>
            <input type="file" name="spotlight_pdf" accept="application/pdf" required className="w-full text-sm" />
          </div>

          <p className="text-xs text-neutral-600">
            The PDF will be stored in your Supabase storage. Automated parsing and profile creation from PDF will be added
            in a later step.
          </p>

          <button
            type="submit"
            className="px-6 py-2 rounded-full bg-neutral-900 text-white text-sm font-medium hover:bg-neutral-800 transition"
          >
            Upload CV (store only)
          </button>
        </form>
      )}
    </div>
  );
}

